args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT ?father ?birthDate WHERE {
  BIND(dbr:Joseph_de_Maistre AS ?father)
  ?father dbo:birthDate ?birthDate .
}

